package com.aayush.shoppingapp.commonimport androidx.compose.foundation.layout.PaddingValuesimport androidx.compose.foundation.layout.paddingimport androidx.compose.runtime.Composableimport androidx.compose.ui.Modifierimport androidx.hilt.lifecycle.viewmodel.compose.hiltViewModelimport androidx.navigation.NavTypeimport androidx.navigation.compose.NavHostimport androidx.navigation.compose.composableimport androidx.navigation.compose.rememberNavControllerimport androidx.navigation.navArgumentimport com.aayush.shoppingapp.common.Enums.ScreenNamesimport com.aayush.shoppingapp.viewModels.CategoriesViewModelimport com.aayush.shoppingapp.viewModels.TaskViewModelimport com.aayush.shoppingapp.views.CategoryScreenimport com.aayush.shoppingapp.views.TaskScreen@Composablefun NavigationHandler(innerPadding: PaddingValues) {    val navController = rememberNavController()    NavHost(        navController,        ScreenNames.Category.name,        modifier = Modifier.padding(innerPadding)) {        composable(ScreenNames.Category.name) {            val viewModel: CategoriesViewModel = hiltViewModel()            CategoryScreen(navController, viewModel)        }        composable(            ScreenNames.Task.name+"/{categoryId}",            arguments = listOf(navArgument("categoryId"){ type = NavType.LongType })        ) {            val taskVm: TaskViewModel = hiltViewModel()            val categoryId:Long = it.arguments?.get("categoryId") as Long            TaskScreen(                navController,                categoryId = categoryId,                taskViewModel = taskVm            )        }    }}